body.script:
// ── Original dev's exact working init ──────────────────────────────────
const connection = new BareMux.BareMuxConnection("/sail/baremux/worker.js")
connection.setTransport("/sail/libcurl/index.mjs", [{ websocket: "wss://wisp.mercurywork.shop/" }])

const { ScramjetController } = $scramjetLoadController()
const scramjet = new ScramjetController({
    files: {
        all:  "/sail/scram/scramjet.all.js",
        wasm: "/sail/scram/scramjet.wasm.wasm",
        sync: "/sail/scram/scramjet.sync.js"
    },
    prefix: "/sail/go/"
})
scramjet.init()
// ──────────────────────────────────────────────────────────────────────

const frame      = document.getElementById("frame")
const bar        = document.getElementById("bar")
const loadingBar = document.getElementById("loading-bar")
const homepage   = document.getElementById("homepage")
const clockEl    = document.getElementById("homeClock")
const dateEl     = document.getElementById("homeDate")

const DAYS   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December']

function updateClock() {
    const now = new Date()
    clockEl.textContent = now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0')
    dateEl.textContent  = DAYS[now.getDay()] + ' · ' + MONTHS[now.getMonth()] + ' ' + now.getDate()
}
updateClock()
setInterval(updateClock, 1000)

function showLoader() {
    loadingBar.style.opacity = '1'
    loadingBar.style.width = '70%'
    loadingBar.style.transition = 'width 1.2s ease'
}
function hideLoader() {
    loadingBar.style.width = '100%'
    loadingBar.style.transition = 'width 0.3s ease, opacity 0.4s ease 0.3s'
    setTimeout(() => { loadingBar.style.opacity = '0'; loadingBar.style.width = '0%'; loadingBar.style.transition = 'none' }, 700)
}

function navigate(rawUrl) {
    let url = rawUrl.trim()
    if (!url) return
    if (!url.includes('.')) {
        url = 'https://search.brave.com/search?q=' + encodeURIComponent(url)
    } else if (!url.startsWith('http://') && !url.startsWith('https://')) {
        url = 'https://' + url
    }
    homepage.classList.add('hidden')
    showLoader()
    bar.value = rawUrl.trim()
    frame.src = scramjet.encodeUrl(url)
}

function nav()        { navigate(bar.value) }
function navHomeBar() { const v = document.getElementById('home-bar').value; navigate(v) }
function shortcutNav(url) { navigate(url) }
function goHome()     { homepage.classList.remove('hidden'); frame.src = ''; bar.value = '' }

frame.addEventListener('load', hideLoader)
bar.addEventListener('keydown', e => { if (e.key === 'Enter') nav() })
document.getElementById('home-bar').addEventListener('keydown', e => { if (e.key === 'Enter') navHomeBar() })

// ── Wisp switcher ─────────────────────────────────────────────────────
function switchWisp() {
    const url = document.getElementById('wispSelect').value
    connection.setTransport('/sail/libcurl/index.mjs', [{ websocket: url }])
    probeWisp(url)
}

// ── Wisp status dot ───────────────────────────────────────────────────
let probeTimer = null
function probeWisp(url) {
    const dot = document.getElementById('statusDot')
    dot.className = 'status-dot checking'
    dot.title = 'Checking…'
    clearTimeout(probeTimer)
    let settled = false, ws
    try { ws = new WebSocket(url) } catch(e) { setStatus(false); return }
    const timeout = setTimeout(() => { if (!settled) { settled = true; setStatus(false); try { ws.close() } catch(_){} } }, 5000)
    ws.onopen  = () => { if (!settled) { settled = true; clearTimeout(timeout); setStatus(true);  try { ws.close() } catch(_){} } }
    ws.onerror = () => { if (!settled) { settled = true; clearTimeout(timeout); setStatus(false) } }
    ws.onclose = e => { if (!settled) { settled = true; clearTimeout(timeout); setStatus(e.code !== 1006) } }
    function setStatus(online) {
        dot.className = 'status-dot ' + (online ? 'online' : 'offline')
        dot.title = online ? 'Connected' : 'Offline'
        probeTimer = setTimeout(() => probeWisp(document.getElementById('wispSelect').value), 30000)
    }
}
probeWisp('wss://wisp.mercurywork.shop/')
